import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%82%AB%E3%82%AD%E3%82%AA%E3%82%AF.html","title":"カキオク","lang":"en-US","frontmatter":{},"git":{"createdTime":1633842886000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":3}]},"readingTime":{"minutes":0.3,"words":90},"filePathRelative":"カキオク.md"}`),a={name:`カキオク.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="カキオク" tabindex="-1"><a class="header-anchor" href="#カキオク"><span>カキオク</span></a></h1><p>手書きで覚えるAnkiっぽいアプリが欲しいなぁ、と思って書いた。</p><ul><li><a href="https://karino2.github.io/2021/06/27/kakioku.html" target="_blank" rel="noopener noreferrer">blog: 書いて覚える暗記アプリ、カキオク</a></li></ul><p>デッキはフォルダ、問題、回答は単なるpngファイルで現在のステータスはテキストファイル、と非常にUnix的な作りになっている。 かなり良い出来と思うけれど、ちょっとユーザー層にリーチする手段がなさ過ぎたかなぁ。</p><p>自分的にはイタリア語の動詞の活用を覚えるためだけに作ったアプリだが、その目的は達成出来た。 やはり手書き特化のアプリはあった方が良いね。</p><h2 id="sm2" tabindex="-1"><a class="header-anchor" href="#sm2"><span>SM2</span></a></h2><p>Ankiなどで使われてるアルゴリズム。</p><ul><li><a href="https://help.remnote.com/en/articles/9337171-understanding-spaced-repetition" target="_blank" rel="noopener noreferrer">Understanding Spaced Repetition - RemNote Help Center</a><ul><li><a href="https://help.remnote.com/en/articles/6026144-the-anki-sm-2-spaced-repetition-algorithm" target="_blank" rel="noopener noreferrer">The Anki SM-2 Spaced Repetition Algorithm - RemNote Help Center</a></li></ul></li></ul>`,8)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};